  width: 100%;
  height: 100%;
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.45;
  overflow: hidden;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Master Layout Structure */
.app-container {
  display: flex;
  flex-direction: column;
  width: 100vw;
  height: 100vh;
  background: radial-gradient(circle at 10% 20%, rgba(157, 78, 221, 0.08) 0%, transparent 40%),
              radial-gradient(circle at 90% 80%, rgba(255, 42, 133, 0.08) 0%, transparent 40%),
              var(--bg-primary);
}

/* Top App Header */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 60px;
  padding: 0 24px;
  background-color: var(--bg-secondary);
  border-bottom: 1px solid var(--border-subtle);
  flex-shrink: 0;
  z-index: 10;
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, var(--neon-pink), var(--neon-orange));
  color: #fff;
  font-family: var(--font-display);
  font-size: 20px;
  letter-spacing: 1px;
  border-radius: var(--radius-sm);
  box-shadow: 0 0 14px var(--neon-pink-glow);
}

.brand-titles {
  display: flex;
  flex-direction: column;
}

.brand-title {
  font-family: var(--font-display);
  font-size: 20px;
  letter-spacing: 1.5px;
  color: #fff;
  text-shadow: 0 2px 8px rgba(0,0,0,0.6);
}

.brand-sub {
  color: var(--neon-pink);
  text-shadow: 0 0 10px var(--neon-pink-glow);
}

.brand-tagline {
  font-size: 10px;
  letter-spacing: 2px;
  color: var(--neon-cyan);
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* App Main Workspace */
.app-workspace {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

/* Canvas Viewport */
.canvas-viewport {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: #06050b;
  background-image: 
    linear-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
  background-size: 32px 32px;
  padding: 24px;
  overflow: hidden;
}

.viewport-canvas-container {
  position: relative;
  max-width: 100%;
  max-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8), 0 0 24px rgba(255, 42, 133, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-sm);
  background-color: #000;
  transition: box-shadow 0.3s ease;
}

#cover-canvas {
  display: block;
  max-width: 100%;
  max-height: calc(100vh - 150px);
  width: auto;
  height: auto;
  object-fit: contain;
}

.render-indicator {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 6px 14px;
  background-color: rgba(10, 9, 17, 0.85);
  color: var(--neon-cyan);
  font-family: var(--font-mono);
  font-size: 11px;
  border: 1px solid var(--neon-cyan);
  border-radius: 20px;
  box-shadow: 0 0 10px var(--neon-cyan-glow);
  pointer-events: none;
}

.render-indicator.hidden {
  display: none;
}

.viewport-hud {
  position: absolute;
  bottom: 16px;
  left: 24px;
  display: flex;
  gap: 10px;
  z-index: 5;
}

.hud-item {
  background-color: rgba(19, 16, 33, 0.85);
  backdrop-filter: blur(8px);
  padding: 4px 12px;
  border-radius: 20px;
  border: 1px solid var(--border-subtle);
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
}

.hud-item.hud-layout {
  color: var(--neon-pink);
  border-color: rgba(255, 42, 133, 0.3);
}

.hud-item.hud-filter {
  color: var(--neon-cyan);
  border-color: rgba(0, 229, 255, 0.3);
}

/* Sidebar Dock */
.sidebar-dock {
  width: 400px;
  background-color: var(--bg-secondary);
  border-left: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  z-index: 8;
}

.sidebar-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Scrollbar Customization */
.sidebar-scroll::-webkit-scrollbar {
  width: 6px;
}
.sidebar-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar-scroll::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 3px;
}
.sidebar-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--neon-pink);
}

/* Sidebar Group Card */
.sidebar-group {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 16px;
  backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  padding-bottom: 8px;
}

.group-title {
  font-family: var(--font-display);
  font-size: 14px;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #fff;
}

.group-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Aspect Ratio Pill Grid */
.ratio-pill-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.ratio-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px 6px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.2s ease;
}

.ratio-pill:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.2);
}

.ratio-pill.active {
  background: linear-gradient(135deg, rgba(255, 42, 133, 0.15), rgba(157, 78, 221, 0.2));
  border-color: var(--neon-pink);
  box-shadow: 0 0 12px var(--neon-pink-glow);
}

.ratio-pill .pill-title {
  font-family: var(--font-display);
  font-size: 16px;
  letter-spacing: 0.5px;
}

.ratio-pill .pill-desc {
  font-size: 10px;
  color: var(--text-muted);
}

/* Layout Pill Grid */
.layout-pill-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
}

.layout-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 4px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.layout-pill:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.layout-pill.active {
  background: rgba(0, 229, 255, 0.12);
  border-color: var(--neon-cyan);
  color: #fff;
  box-shadow: 0 0 10px var(--neon-cyan-glow);
}

.layout-icon {
  width: 28px;
  height: 20px;
  border: 1px dashed rgba(255, 255, 255, 0.3);
  border-radius: 2px;
  position: relative;
}

.layout-icon-hero {
  border-style: solid;
  border-color: var(--neon-cyan);
}

.layout-icon-triptych::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 33%;
  right: 33%;
  border-left: 1px solid rgba(255, 255, 255, 0.4);
  border-right: 1px solid rgba(255, 255, 255, 0.4);
}

.layout-icon-quad::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.4);
}
.layout-icon-quad::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  border-left: 1px solid rgba(255, 255, 255, 0.4);
}

.layout-icon-epic::before {
  content: '';
  position: absolute;
  left: 45%;
  top: 0;
  bottom: 0;
  border-left: 1px solid rgba(255, 255, 255, 0.4);
}

.layout-icon-slash {
  background: linear-gradient(135deg, transparent 48%, rgba(255, 255, 255, 0.5) 49%, rgba(255, 255, 255, 0.5) 51%, transparent 52%);
}

/* Slot Controls List */
.slot-controls-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.slot-item-card {
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.slot-item-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.slot-name {
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: 0.5px;
  color: var(--neon-cyan);
}

.slot-file-btn {
  font-size: 11px;
  color: var(--neon-pink);
  cursor: pointer;
  text-decoration: underline;
}

/* Filter Pills */
.filter-pill-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.filter-pill {
  padding: 8px 4px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  text-align: center;
  transition: all 0.2s ease;
}

.filter-pill:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.filter-pill.active {
  background: linear-gradient(135deg, rgba(255, 42, 133, 0.2), rgba(0, 229, 255, 0.2));
  border-color: var(--neon-pink);
  color: #fff;
  box-shadow: 0 0 10px var(--neon-pink-glow);
}

/* Form Controls, Inputs & Sliders */
.input-control {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-control label {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ui-input {
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  color: #fff;
  font-family: var(--font-ui);
  font-size: 13px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.ui-input:focus {
  outline: none;
  border-color: var(--neon-pink);
  box-shadow: 0 0 8px var(--neon-pink-glow);
}

.ui-select {
  background: rgba(19, 16, 33, 0.95);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  color: #fff;
  font-family: var(--font-ui);
  font-size: 12px;
  cursor: pointer;
  outline: none;
}

.ui-select:focus {
  border-color: var(--neon-cyan);
}

.toggle-control-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.toggle-label {
  font-size: 12px;
  color: var(--text-main);
  cursor: pointer;
}

.ui-switch {
  appearance: none;
  width: 36px;
  height: 20px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  position: relative;
  cursor: pointer;
  transition: background 0.2s ease;
}

.ui-switch::before {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.2s ease;
}

.ui-switch:checked {
  background: var(--neon-pink);
  box-shadow: 0 0 8px var(--neon-pink-glow);
}

.ui-switch:checked::before {
  transform: translateX(16px);
}

/* Sliders */
.slider-control {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.slider-label-row {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
}

.slider-label-row label {
  color: var(--text-muted);
}

.slider-val {
  font-family: var(--font-mono);
  color: var(--neon-cyan);
}

.ui-slider {
  appearance: none;
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  outline: none;
}

.ui-slider::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--neon-cyan);
  cursor: pointer;
  box-shadow: 0 0 6px var(--neon-cyan-glow);
  transition: transform 0.1s ease;
}

.ui-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

/* Action Buttons */
.ui-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 16px;
  font-family: var(--font-ui);
  font-weight: 600;
  font-size: 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: none;
  transition: all 0.2s ease;
}

.ui-btn-primary {
  background: linear-gradient(135deg, var(--neon-pink), var(--neon-orange));
  color: #fff;
  box-shadow: 0 0 12px var(--neon-pink-glow);
}

.ui-btn-primary:hover {
  filter: brightness(1.15);
  box-shadow: 0 0 18px var(--neon-pink-glow);
}

.export-btn-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ui-btn-action {
  background: linear-gradient(135deg, rgba(255, 42, 133, 0.25), rgba(157, 78, 221, 0.25));
  border: 1px solid var(--neon-pink);
  color: #fff;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.ui-btn-action:hover {
  background: linear-gradient(135deg, rgba(255, 42, 133, 0.4), rgba(157, 78, 221, 0.4));
  box-shadow: 0 0 14px var(--neon-pink-glow);
}

.ui-btn-action small {
  font-size: 10px;
  color: var(--neon-cyan);
  margin-top: 2px;
}

.ui-btn-secondary {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.ui-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.2);
}

.ui-btn-secondary small {
  font-size: 10px;
  color: var(--text-muted);
}

.ui-btn-outline {
  background: transparent;
  border: 1px solid var(--border-subtle);
  color: var(--text-dim);
  padding: 6px 12px;
}

.ui-btn-outline:hover {
  color: var(--text-main);
  border-color: var(--text-muted);
}

/* Responsive Media Queries */
@media (max-width: 992px) {
  .app-workspace {
    flex-direction: column;
  }
  .sidebar-dock {
    width: 100%;
    height: 380px;
    border-left: none;
    border-top: 1px solid var(--border-subtle);
  }
}
